import React from 'react';

const Header = () => {
    return (
        <header style={headerStyle}>
            <h1>My React App</h1>
            <nav>
                <ul style={navStyle}>
                    <li><a href="/">Home</a></li>
                    <li><a href="/about">About</a></li>
                    <li><a href="/contact">Contact</a></li>
                </ul>
            </nav>
        </header>
    );
};

const headerStyle = {
    backgroundColor: '#282c34',
    padding: '10px',
    color: 'white',
    textAlign: 'center',
};

const navStyle = {
    listStyleType: 'none',
    display: 'flex',
    justifyContent: 'center',
    padding: 0,
};

export default Header;
